from queue import Queue
from threading import Thread

q = Queue()
for item in items:
    q.put(item)
for _ in range(4):
    q.put(None)

def worker():
    while True:
        item = q.get()
        try:
            if item is None:
                return
            process(item)
        finally:
            q.task_done()

threads = [Thread(target=worker) for _ in range(4)]
for thread in threads:
    thread.start()
q.join()
for thread in threads:
    thread.join()

