def call_with_retry(max_attempts=3):
    if max_attempts < 1:
        raise ValueError("max_attempts must be positive")
    for attempt in range(max_attempts):
        try:
            return call_api()
        except TimeoutError:
            if attempt == max_attempts - 1:
                raise
            wait = 2 ** attempt + random.uniform(0, 0.5)
            time.sleep(wait)

