import time

def get_or_fetch(key, cache, fetch, ttl=3600):
    item = cache.get(key)
    if item and time.time() - item["saved_at"] < ttl:
        return item["value"]
    value = fetch(key)
    cache[key] = {"value": value, "saved_at": time.time()}
    return value

